from unittest import mock

import pytest

from notifier import email


@pytest.mark.parametrize("flag, template", [
    (None, "receipt"),
    ("0", "receipt"),
    ("1", "receipt_v2"),
])
def test_send_receipt_template_follows_flag(monkeypatch, flag, template):
    if flag is None:
        monkeypatch.delenv("NOTIFIER_FF_RECEIPT_V2", raising=False)
    else:
        monkeypatch.setenv("NOTIFIER_FF_RECEIPT_V2", flag)
    with mock.patch.object(email, "render", return_value="<p>hi</p>") as render, \
            mock.patch.object(email, "send", return_value="msg_1"):
        assert email.send_receipt("inv_1", "a@example.com", 1200) == "msg_1"
    render.assert_called_once_with(template, invoice_id="inv_1", total_minor=1200)
EOF
